CREATE TABLE ibexa_content_field (id INT AUTO_INCREMENT NOT NULL, version INT DEFAULT 0 NOT NULL, attribute_original_id INT DEFAULT 0, content_type_field_definition_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT 0 NOT NULL, data_float DOUBLE PRECISION DEFAULT NULL, data_int INT DEFAULT NULL, data_text LONGTEXT DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '', language_code VARCHAR(20) DEFAULT '' NOT NULL, language_id BIGINT DEFAULT 0 NOT NULL, sort_key_int INT DEFAULT 0 NOT NULL, sort_key_string VARCHAR(255) DEFAULT '' NOT NULL, INDEX ibexa_content_field_co_id_ver_lang_code (contentobject_id, version, language_code), INDEX ibexa_content_field_field_definition_id (content_type_field_definition_id), INDEX sort_key_string (sort_key_string(191)), INDEX ibexa_content_field_language_code (language_code), INDEX sort_key_int (sort_key_int), INDEX ibexa_content_field_co_id_ver (contentobject_id, version), PRIMARY KEY(id, version)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
